package com.example.suxml;

import org.springframework.boot.SpringApplication;
import org.springframework.boot.autoconfigure.SpringBootApplication;

/**
 * Entry point for the SUXML Spring Boot application.
 *
 * <p>Migrated from COBOL program SUXML (PASSENGER-SUXML-SUBPROG).
 * The original program read an XML file containing up to 81 passenger
 * records, parsed each element by tag name, and stored the values in a
 * COBOL table that was passed back via the LINKAGE SECTION.  This
 * application exposes that behaviour as a REST API that accepts an XML
 * file upload, parses it, persists the passengers to PostgreSQL, and
 * returns the parsed list as JSON.
 */
@SpringBootApplication
public class Application {

    public static void main(String[] args) {
        SpringApplication.run(Application.class, args);
    }
}

