package com.example.suxml.model;

import jakarta.persistence.*;

/**
 * JPA entity that maps to the {@code passenger} table in PostgreSQL.
 *
 * <p>Field sizes mirror the COBOL LINKAGE SECTION exactly:
 * <pre>
 *   FIRSTNAME   PIC X(30)
 *   LASTNAME    PIC X(30)
 *   ADDRE       PIC X(250)
 *   CITY        PIC X(50)
 *   COUNTRY     PIC X(30)
 *   ZIPCODE     PIC X(15)
 *   TELEPHONE   PIC X(18)
 *   EMAIL       PIC X(100)
 * </pre>
 */
@Entity
@Table(name = "passenger")
public class Passenger {

    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    @Column(name = "id")
    private Long id;

    /** Mirrors COBOL field FIRSTNAME PIC X(30). */
    @Column(name = "firstname", length = 30)
    private String firstname;

    /** Mirrors COBOL field LASTNAME PIC X(30). */
    @Column(name = "lastname", length = 30)
    private String lastname;

    /** Mirrors COBOL field ADDRE PIC X(250). */
    @Column(name = "addre", length = 250)
    private String addre;

    /** Mirrors COBOL field CITY PIC X(50). */
    @Column(name = "city", length = 50)
    private String city;

    /** Mirrors COBOL field COUNTRY PIC X(30). */
    @Column(name = "country", length = 30)
    private String country;

    /** Mirrors COBOL field ZIPCODE PIC X(15). */
    @Column(name = "zipcode", length = 15)
    private String zipcode;

    /** Mirrors COBOL field TELEPHONE PIC X(18). */
    @Column(name = "telephone", length = 18)
    private String telephone;

    /** Mirrors COBOL field EMAIL PIC X(100). */
    @Column(name = "email", length = 100)
    private String email;

    // ----------------------------------------------------------------
    // Constructors
    // ----------------------------------------------------------------

    public Passenger() {}

    public Passenger(String firstname, String lastname, String addre,
                     String city, String country, String zipcode,
                     String telephone, String email) {
        this.firstname = firstname;
        this.lastname  = lastname;
        this.addre     = addre;
        this.city      = city;
        this.country   = country;
        this.zipcode   = zipcode;
        this.telephone = telephone;
        this.email     = email;
    }

    // ----------------------------------------------------------------
    // Getters & Setters
    // ----------------------------------------------------------------

    public Long getId()                     { return id; }
    public void setId(Long id)              { this.id = id; }

    public String getFirstname()            { return firstname; }
    public void setFirstname(String v)      { this.firstname = truncate(v, 30); }

    public String getLastname()             { return lastname; }
    public void setLastname(String v)       { this.lastname = truncate(v, 30); }

    public String getAddre()                { return addre; }
    public void setAddre(String v)          { this.addre = truncate(v, 250); }

    public String getCity()                 { return city; }
    public void setCity(String v)           { this.city = truncate(v, 50); }

    public String getCountry()              { return country; }
    public void setCountry(String v)        { this.country = truncate(v, 30); }

    public String getZipcode()              { return zipcode; }
    public void setZipcode(String v)        { this.zipcode = truncate(v, 15); }

    public String getTelephone()            { return telephone; }
    public void setTelephone(String v)      { this.telephone = truncate(v, 18); }

    public String getEmail()                { return email; }
    public void setEmail(String v)          { this.email = truncate(v, 100); }

    // ----------------------------------------------------------------
    // Helpers
    // ----------------------------------------------------------------

    /**
     * Replicates the COBOL MOVE semantics for PIC X(n): if the source
     * string is longer than the target field width it is truncated;
     * trailing spaces are preserved as-is (trimming is left to callers).
     */
    private static String truncate(String value, int maxLength) {
        if (value == null) return null;
        return value.length() > maxLength ? value.substring(0, maxLength) : value;
    }

    @Override
    public String toString() {
        return "Passenger{id=%d, firstname='%s', lastname='%s', email='%s'}"
                .formatted(id, firstname, lastname, email);
    }
}

