package com.example.suxml.dto;

import jakarta.validation.constraints.Email;
import jakarta.validation.constraints.Size;

/**
 * Immutable DTO (Java 17 record) that represents a single passenger
 * entry parsed from the XML file.
 *
 * <p>Field constraints mirror the COBOL PIC X(n) field widths so that
 * validation rejects data that would have been silently truncated on the
 * mainframe.
 */
public record PassengerDto(

        @Size(max = 30, message = "firstname must not exceed 30 characters")
        String firstname,

        @Size(max = 30, message = "lastname must not exceed 30 characters")
        String lastname,

        @Size(max = 250, message = "addre must not exceed 250 characters")
        String addre,

        @Size(max = 50, message = "city must not exceed 50 characters")
        String city,

        @Size(max = 30, message = "country must not exceed 30 characters")
        String country,

        @Size(max = 15, message = "zipcode must not exceed 15 characters")
        String zipcode,

        @Size(max = 18, message = "telephone must not exceed 18 characters")
        String telephone,

        @Email(message = "email must be a valid e-mail address")
        @Size(max = 100, message = "email must not exceed 100 characters")
        String email
) {}

