package com.example.suxml.repository;

import com.example.suxml.model.Passenger;
import org.springframework.data.jpa.repository.JpaRepository;
import org.springframework.data.jpa.repository.Query;
import org.springframework.data.repository.query.Param;
import org.springframework.stereotype.Repository;

import java.util.List;

/**
 * Spring Data JPA repository for {@link Passenger} entities.
 */
@Repository
public interface PassengerRepository extends JpaRepository<Passenger, Long> {

    /**
     * Finds passengers whose e-mail matches exactly (case-insensitive).
     *
     * @param email the e-mail address to search for
     * @return matching passengers
     */
    @Query("SELECT p FROM Passenger p WHERE LOWER(p.email) = LOWER(:email)")
    List<Passenger> findByEmailIgnoreCase(@Param("email") String email);

    /**
     * Finds passengers by last name (case-insensitive, partial match).
     *
     * @param lastname partial or full last name
     * @return matching passengers
     */
    @Query("SELECT p FROM Passenger p WHERE LOWER(p.lastname) LIKE LOWER(CONCAT('%', :lastname, '%'))")
    List<Passenger> findByLastnameContainingIgnoreCase(@Param("lastname") String lastname);
}

