package com.example.suxml.service;

import com.example.suxml.dto.PassengerDto;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.stereotype.Service;
import org.w3c.dom.Document;
import org.w3c.dom.Element;
import org.w3c.dom.NodeList;
import org.xml.sax.InputSource;

import javax.xml.parsers.DocumentBuilder;
import javax.xml.parsers.DocumentBuilderFactory;
import java.io.StringReader;
import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.List;

/**
 * Parses a UTF-8 XML document containing passenger records and returns
 * a list of {@link PassengerDto} objects.
 *
 * <p>This service replicates the behaviour of the following COBOL
 * paragraphs:
 * <ul>
 *   <li>{@code 0300-CONVERT-XML} – converts raw bytes to a usable
 *       character representation (DISPLAY-OF / NATIONAL-OF in COBOL;
 *       here we simply decode using UTF-8 which is equivalent).</li>
 *   <li>{@code 0310-HANDLER-XML} – the XML PARSE event handler that
 *       inspects {@code XML-EVENT} and {@code XML-HEAD} (element name)
 *       to populate the PASSENGER-TABLE entries.</li>
 * </ul>
 *
 * <p>COBOL enforced a hard limit of 81 passenger entries (OCCURS 81).
 * That limit is preserved here: any records beyond index 81 are silently
 * discarded, exactly as the COBOL program would overflow COUNT1 past the
 * table boundary.
 */
@Service
public class XmlParserService {

    /** Maximum table size from COBOL: PASSENGER-TABLE OCCURS 81. */
    public static final int MAX_PASSENGERS = 81;

    private static final Logger log = LoggerFactory.getLogger(XmlParserService.class);

    /**
     * Parses raw XML bytes (UTF-8) and extracts up to
     * {@value #MAX_PASSENGERS} passenger records.
     *
     * <p>Mirrors {@code 0300-CONVERT-XML} + {@code 0310-HANDLER-XML}.
     *
     * @param xmlBytes raw bytes of the XML file (UTF-8 encoded)
     * @return list of parsed passengers (at most {@value #MAX_PASSENGERS})
     * @throws XmlParseException if the XML is malformed or cannot be parsed
     */
    public List<PassengerDto> parse(byte[] xmlBytes) {
        // 0300-CONVERT-XML: DISPLAY-OF(NATIONAL-OF(PASSENGER-XML, 1208), 1047)
        // In Java: the file is already UTF-8; decode to String.
        String xmlDoc = new String(xmlBytes, StandardCharsets.UTF_8);
        log.debug("XML document length (chars): {}", xmlDoc.length());

        Document document = buildDocument(xmlDoc);
        return extractPassengers(document);
    }

    // ----------------------------------------------------------------
    // Private helpers
    // ----------------------------------------------------------------

    /**
     * Builds a DOM {@link Document} from the XML string.
     * Equivalent to the {@code XML PARSE} statement in COBOL.
     */
    private Document buildDocument(String xmlDoc) {
        try {
            DocumentBuilderFactory factory = DocumentBuilderFactory.newInstance();
            // Protect against XXE
            factory.setFeature("http://apache.org/xml/features/disallow-doctype-decl", true);
            factory.setNamespaceAware(false);

            DocumentBuilder builder = factory.newDocumentBuilder();
            return builder.parse(new InputSource(new StringReader(xmlDoc)));
        } catch (Exception ex) {
            log.error("XML parse failed: {}", ex.getMessage());
            throw new XmlParseException("Failed to parse XML document: " + ex.getMessage(), ex);
        }
    }

    /**
     * Walks the DOM and populates the passenger list.
     *
     * <p>This replicates the {@code 0310-HANDLER-XML} paragraph:
     * <ul>
     *   <li>{@code WHEN 'START-OF-ELEMENT'} → element tag name captured
     *       into {@code XML-HEAD}.</li>
     *   <li>{@code WHEN 'CONTENT-CHARACTERS'} → text content dispatched
     *       by {@code XML-HEAD} value to the corresponding passenger
     *       field.</li>
     *   <li>{@code ADD 1 TO COUNT1} after EMAIL → increment row counter
     *       (here: finalise the current builder and start a new one).</li>
     * </ul>
     *
     * The COBOL counter starts at 1 and is incremented only when EMAIL
     * is encountered, so each complete passenger block ends with EMAIL.
     */
    private List<PassengerDto> extractPassengers(Document document) {
        List<PassengerDto> result = new ArrayList<>();

        // Locate all <PASSENGER> elements (or whatever the repeating element
        // is called).  We support two layouts:
        //   Layout A – a <PASSENGERS> root with <PASSENGER> children.
        //   Layout B – the root element itself contains the tag fields
        //              directly repeated (flat structure).
        // We attempt Layout A first; fall back to Layout B.
        NodeList passengerNodes = document.getElementsByTagName("PASSENGER");

        if (passengerNodes.getLength() > 0) {
            // Layout A – structured
            int limit = Math.min(passengerNodes.getLength(), MAX_PASSENGERS);
            for (int i = 0; i < limit; i++) {
                Element el = (Element) passengerNodes.item(i);
                PassengerDto dto = buildDtoFromElement(el, i + 1);
                result.add(dto);
            }
        } else {
            // Layout B – flat: parse sibling groups sharing a common parent
            result = parseFlatXml(document);
        }

        log.debug("Total passengers parsed: {}", result.size());
        return result;
    }

    /**
     * Builds a {@link PassengerDto} from an XML {@code <PASSENGER>}
     * element by inspecting child element tag names – mirroring the
     * {@code EVALUATE XML-HEAD} dispatch in {@code 0310-HANDLER-XML}.
     *
     * @param el      the {@code <PASSENGER>} DOM element
     * @param count1  the COBOL COUNT1 value (1-based row index, for logging)
     */
    private PassengerDto buildDtoFromElement(Element el, int count1) {
        // WHEN 'FIRSTNAME'
        String firstname = getTextContent(el, "FIRSTNAME");
        log.debug("FIRSTNAME({}) = {}", count1, firstname);

        // WHEN 'LASTNAME'
        String lastname = getTextContent(el, "LASTNAME");
        log.debug("LASTNAME({}) = {}", count1, lastname);

        // WHEN 'ADDRE'
        String addre = getTextContent(el, "ADDRE");
        log.debug("ADDRE({}) = {}", count1, addre);

        // WHEN 'CITY'
        String city = getTextContent(el, "CITY");
        log.debug("CITY({}) = {}", count1, city);

        // WHEN 'COUNTRY'
        String country = getTextContent(el, "COUNTRY");
        log.debug("COUNTRY({}) = {}", count1, country);

        // WHEN 'ZIPCODE'
        String zipcode = getTextContent(el, "ZIPCODE");
        log.debug("ZIPCODE({}) = {}", count1, zipcode);

        // WHEN 'TELEPHONE'
        String telephone = getTextContent(el, "TELEPHONE");
        log.debug("TELEPHONE({}) = {}", count1, telephone);

        // WHEN 'EMAIL' – triggers ADD 1 TO COUNT1 in COBOL
        String email = getTextContent(el, "EMAIL");
        log.debug("EMAIL({}) = {} → incrementing count", count1, email);

        return new PassengerDto(
                truncate(firstname, 30),
                truncate(lastname,  30),
                truncate(addre,     250),
                truncate(city,      50),
                truncate(country,   30),
                truncate(zipcode,   15),
                truncate(telephone, 18),
                truncate(email,     100)
        );
    }

    /**
     * Handles flat XML documents where the passenger fields appear as
     * direct children of the root element, repeated sequentially.
     *
     * <p>This reproduces the original COBOL event-driven parser
     * ({@code 0310-HANDLER-XML}) as closely as possible: it walks every
     * child element in document order, dispatches on tag name, and
     * increments the row counter ({@code COUNT1}) when the EMAIL tag is
     * encountered – exactly mirroring {@code ADD 1 TO COUNT1}.
     */
    private List<PassengerDto> parseFlatXml(Document document) {
        List<PassengerDto> result = new ArrayList<>();

        // Mutable state mirroring COBOL working-storage
        int count1 = 1;                    // COBOL: COUNT1 PIC 9(5) VALUE 1
        String xmlHead = "";              // COBOL: XML-HEAD PIC X(20)

        // Passenger builder fields (mirroring the LINKAGE SECTION table row)
        String firstname = "";
        String lastname  = "";
        String addre     = "";
        String city      = "";
        String country   = "";
        String zipcode   = "";
        String telephone = "";
        String email     = "";

        // Collect all leaf elements in document order from the root
        NodeList allElements = document.getDocumentElement().getChildNodes();

        for (int n = 0; n < allElements.getLength(); n++) {
            if (!(allElements.item(n) instanceof Element el)) continue;

            // WHEN 'START-OF-ELEMENT': MOVE XML-TEXT TO XML-HEAD
            xmlHead = el.getTagName().toUpperCase();
            // WHEN 'CONTENT-CHARACTERS': EVALUATE XML-HEAD
            String xmlText = el.getTextContent();

            switch (xmlHead) {
                case "FIRSTNAME" -> {
                    firstname = truncate(xmlText, 30);
                    log.debug("FIRSTNAME({}) = {}", count1, firstname);
                }
                case "LASTNAME" -> {
                    lastname = truncate(xmlText, 30);
                    log.debug("LASTNAME({}) = {}", count1, lastname);
                }
                case "ADDRE" -> {
                    addre = truncate(xmlText, 250);
                    log.debug("ADDRE({}) = {}", count1, addre);
                }
                case "CITY" -> {
                    city = truncate(xmlText, 50);
                    log.debug("CITY({}) = {}", count1, city);
                }
                case "COUNTRY" -> {
                    country = truncate(xmlText, 30);
                    log.debug("COUNTRY({}) = {}", count1, country);
                }
                case "ZIPCODE" -> {
                    zipcode = truncate(xmlText, 15);
                    log.debug("ZIPCODE({}) = {}", count1, zipcode);
                }
                case "TELEPHONE" -> {
                    telephone = truncate(xmlText, 18);
                    log.debug("TELEPHONE({}) = {}", count1, telephone);
                }
                case "EMAIL" -> {
                    email = truncate(xmlText, 100);
                    log.debug("EMAIL({}) = {}", count1, email);

                    // ADD 1 TO COUNT1 – commit this passenger row
                    if (count1 <= MAX_PASSENGERS) {
                        result.add(new PassengerDto(
                                firstname, lastname, addre, city,
                                country, zipcode, telephone, email));
                    } else {
                        log.warn("MAX_PASSENGERS ({}) reached; discarding record {}",
                                MAX_PASSENGERS, count1);
                    }
                    count1++;

                    // Reset row accumulators
                    firstname = ""; lastname  = ""; addre = "";
                    city      = ""; country   = ""; zipcode = "";
                    telephone = ""; email     = "";
                }
                default -> log.trace("Unrecognised element <{}>; skipping", xmlHead);
            }
        }
        return result;
    }

    // ----------------------------------------------------------------
    // Utility
    // ----------------------------------------------------------------

    /** Extracts the trimmed text content of the first matching child tag. */
    private String getTextContent(Element parent, String tagName) {
        NodeList nl = parent.getElementsByTagName(tagName);
        if (nl.getLength() == 0) return "";
        return nl.item(0).getTextContent().trim();
    }

    /**
     * Truncates {@code value} to {@code maxLength} characters, replicating
     * COBOL's MOVE to PIC X(n) truncation behaviour.
     */
    private String truncate(String value, int maxLength) {
        if (value == null) return "";
        return value.length() > maxLength ? value.substring(0, maxLength) : value;
    }
}

