package com.example.suxml.service;

/**
 * Thrown when the XML passenger file cannot be parsed.
 *
 * <p>Equivalent to the COBOL {@code ON EXCEPTION} branch of the
 * {@code XML PARSE} statement (commented out in the original source but
 * preserved here as a proper exception).
 */
public class XmlParseException extends RuntimeException {

    public XmlParseException(String message) {
        super(message);
    }

    public XmlParseException(String message, Throwable cause) {
        super(message, cause);
    }
}

