package com.example.suxml.service;

import com.example.suxml.dto.PassengerDto;
import com.example.suxml.dto.PassengerListResponse;
import com.example.suxml.model.Passenger;
import com.example.suxml.repository.PassengerRepository;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.web.multipart.MultipartFile;

import java.io.IOException;
import java.util.List;

/**
 * Orchestrates the full passenger-import workflow originally implemented
 * across the four top-level COBOL paragraphs:
 *
 * <ol>
 *   <li>{@code 0100-OPEN-FILE}  → {@link #openFile(MultipartFile)} (read bytes)</li>
 *   <li>{@code 0200-READ-FILE}  → embedded in {@link #processXmlFile(MultipartFile)}</li>
 *   <li>{@code 0300-CONVERT-XML} → delegated to {@link XmlParserService#parse(byte[])}</li>
 *   <li>{@code 0400-CLOSE-FILE} → resources closed automatically (try-with-resources)</li>
 * </ol>
 */
@Service
public class PassengerService {

    private static final Logger log = LoggerFactory.getLogger(PassengerService.class);

    private final XmlParserService xmlParserService;
    private final PassengerRepository passengerRepository;

    /** Constructor injection – no field @Autowired. */
    public PassengerService(XmlParserService xmlParserService,
                            PassengerRepository passengerRepository) {
        this.xmlParserService    = xmlParserService;
        this.passengerRepository = passengerRepository;
    }

    // ----------------------------------------------------------------
    // Public API
    // ----------------------------------------------------------------

    /**
     * Reads the uploaded XML file, parses it, persists the passengers,
     * and returns the full list.
     *
     * <p>Mirrors the top-level {@code PROCEDURE DIVISION} flow:
     * OPEN → READ → CONVERT-XML → (persist) → CLOSE.
     *
     * @param file multipart XML file sent by the client
     * @return response containing the count and the list of saved passengers
     */
    @Transactional
    public PassengerListResponse processXmlFile(MultipartFile file) {

        // 0100-OPEN-FILE / 0200-READ-FILE
        byte[] xmlBytes = openFile(file);

        // 0300-CONVERT-XML + 0310-HANDLER-XML
        List<PassengerDto> dtos = xmlParserService.parse(xmlBytes);
        log.info("Parsed {} passenger record(s) from '{}'", dtos.size(), file.getOriginalFilename());

        // Persist to PostgreSQL (replaces COBOL LINKAGE SECTION table output)
        List<Passenger> entities = dtos.stream()
                .map(this::toEntity)
                .toList();

        List<Passenger> saved = passengerRepository.saveAll(entities);
        log.info("Persisted {} passenger record(s)", saved.size());

        // Build response
        List<PassengerDto> savedDtos = saved.stream()
                .map(this::toDto)
                .toList();

        return new PassengerListResponse(savedDtos.size(), savedDtos);
    }

    /**
     * Returns all passengers currently stored in the database.
     *
     * @return list of passenger DTOs
     */
    @Transactional(readOnly = true)
    public List<PassengerDto> findAll() {
        return passengerRepository.findAll()
                .stream()
                .map(this::toDto)
                .toList();
    }

    /**
     * Returns a single passenger by primary key.
     *
     * @param id the passenger's database ID
     * @return the passenger DTO
     * @throws PassengerNotFoundException if no passenger exists with that ID
     */
    @Transactional(readOnly = true)
    public PassengerDto findById(Long id) {
        Passenger p = passengerRepository.findById(id)
                .orElseThrow(() -> new PassengerNotFoundException(id));
        return toDto(p);
    }

    // ----------------------------------------------------------------
    // Private helpers
    // ----------------------------------------------------------------

    /**
     * Reads all bytes from the uploaded file.
     *
     * <p>Mirrors {@code 0100-OPEN-FILE} and {@code 0200-READ-FILE}:
     * the COBOL program opened the file and read it into
     * {@code PASSENGER-XML PIC X(25000)} in a single READ statement.
     *
     * @param file the uploaded multipart file
     * @return raw bytes of the file
     */
    private byte[] openFile(MultipartFile file) {
        if (file == null || file.isEmpty()) {
            log.error("THE FILE COULD NOT BE OPEN");
            throw new XmlParseException("Uploaded file is empty or missing");
        }
        try {
            log.debug("OPEN OK – reading '{}' ({} bytes)",
                    file.getOriginalFilename(), file.getSize());
            byte[] bytes = file.getBytes();
            log.debug("READ OK – {} bytes read", bytes.length);
            // 0400-CLOSE-FILE: resource is released automatically after getBytes()
            log.debug("CLOSE OK");
            return bytes;
        } catch (IOException ex) {
            log.error("THE PROGRAM COULD NOT READ THE FILE – ERROR: {}", ex.getMessage());
            throw new XmlParseException("Could not read uploaded file: " + ex.getMessage(), ex);
        }
    }

    /** Maps a {@link PassengerDto} to a {@link Passenger} JPA entity. */
    private Passenger toEntity(PassengerDto dto) {
        Passenger p = new Passenger();
        p.setFirstname(dto.firstname());
        p.setLastname(dto.lastname());
        p.setAddre(dto.addre());
        p.setCity(dto.city());
        p.setCountry(dto.country());
        p.setZipcode(dto.zipcode());
        p.setTelephone(dto.telephone());
        p.setEmail(dto.email());
        return p;
    }

    /** Maps a {@link Passenger} JPA entity to a {@link PassengerDto}. */
    private PassengerDto toDto(Passenger p) {
        return new PassengerDto(
                p.getFirstname(),
                p.getLastname(),
                p.getAddre(),
                p.getCity(),
                p.getCountry(),
                p.getZipcode(),
                p.getTelephone(),
                p.getEmail()
        );
    }
}

