package com.example.suxml.controller;

import com.example.suxml.dto.PassengerDto;
import com.example.suxml.dto.PassengerListResponse;
import com.example.suxml.service.PassengerService;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.http.MediaType;
import org.springframework.http.ResponseEntity;
import org.springframework.web.bind.annotation.*;
import org.springframework.web.multipart.MultipartFile;

import java.util.List;

/**
 * REST controller exposing the passenger XML-import and query endpoints.
 *
 * <p>The primary endpoint ({@code POST /api/passengers/upload}) is the
 * direct equivalent of invoking the COBOL subprogram SUXML: it accepts
 * an XML file, parses it, persists the records, and returns the parsed
 * list as JSON.
 */
@RestController
@RequestMapping("/api/passengers")
public class PassengerController {

    private static final Logger log = LoggerFactory.getLogger(PassengerController.class);

    private final PassengerService passengerService;

    public PassengerController(PassengerService passengerService) {
        this.passengerService = passengerService;
    }

    // ----------------------------------------------------------------
    // POST /api/passengers/upload
    // ----------------------------------------------------------------

    /**
     * Accepts a multipart XML file upload, parses it (up to 81 passengers),
     * persists the results to PostgreSQL, and returns the saved records.
     *
     * <p>This endpoint is the direct Java replacement for calling the COBOL
     * subprogram SUXML via {@code CALL 'SUXML' USING PASSENGER-LIST}.
     *
     * @param file the XML file (multipart/form-data, field name = "file")
     * @return 200 OK with {@link PassengerListResponse} on success
     */
    @PostMapping(
            value = "/upload",
            consumes = MediaType.MULTIPART_FORM_DATA_VALUE,
            produces = MediaType.APPLICATION_JSON_VALUE
    )
    public ResponseEntity<PassengerListResponse> uploadXml(
            @RequestParam("file") MultipartFile file) {

        log.info("Received XML upload: name='{}', size={} bytes",
                file.getOriginalFilename(), file.getSize());

        PassengerListResponse response = passengerService.processXmlFile(file);
        return ResponseEntity.ok(response);
    }

    // ----------------------------------------------------------------
    // GET /api/passengers
    // ----------------------------------------------------------------

    /**
     * Returns all passenger records stored in the database.
     *
     * @return 200 OK with a list of {@link PassengerDto}
     */
    @GetMapping(produces = MediaType.APPLICATION_JSON_VALUE)
    public ResponseEntity<List<PassengerDto>> getAllPassengers() {
        List<PassengerDto> passengers = passengerService.findAll();
        return ResponseEntity.ok(passengers);
    }

    // ----------------------------------------------------------------
    // GET /api/passengers/{id}
    // ----------------------------------------------------------------

    /**
     * Returns a single passenger by database ID.
     *
     * @param id the passenger's primary key
     * @return 200 OK with the {@link PassengerDto}, or 404 if not found
     */
    @GetMapping(value = "/{id}", produces = MediaType.APPLICATION_JSON_VALUE)
    public ResponseEntity<PassengerDto> getPassengerById(@PathVariable Long id) {
        PassengerDto dto = passengerService.findById(id);
        return ResponseEntity.ok(dto);
    }
}

