package com.example.suxml.config;

import com.example.suxml.dto.ErrorResponse;
import com.example.suxml.service.PassengerNotFoundException;
import com.example.suxml.service.XmlParseException;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.http.HttpStatus;
import org.springframework.http.ResponseEntity;
import org.springframework.web.bind.annotation.ExceptionHandler;
import org.springframework.web.bind.annotation.RestControllerAdvice;
import org.springframework.web.multipart.MaxUploadSizeExceededException;

import java.time.LocalDateTime;

/**
 * Global exception handler that maps application exceptions to
 * structured HTTP error responses.
 *
 * <p>Mirrors the error-display logic in the COBOL paragraphs
 * ({@code DISPLAY 'ERROR: ' FS-PASSENGER-FILE}) but returns proper
 * HTTP status codes instead of writing to SYSOUT.
 */
@RestControllerAdvice
public class GlobalExceptionHandler {

    private static final Logger log = LoggerFactory.getLogger(GlobalExceptionHandler.class);

    /**
     * Handles XML parse failures (equivalent to COBOL {@code ON EXCEPTION}
     * in the {@code XML PARSE} statement).
     */
    @ExceptionHandler(XmlParseException.class)
    public ResponseEntity<ErrorResponse> handleXmlParseException(XmlParseException ex) {
        log.error("XML parse error: {}", ex.getMessage());
        return ResponseEntity
                .status(HttpStatus.UNPROCESSABLE_ENTITY)
                .body(buildError(HttpStatus.UNPROCESSABLE_ENTITY, "XML Parse Error", ex.getMessage()));
    }

    /**
     * Handles passenger-not-found (HTTP 404).
     */
    @ExceptionHandler(PassengerNotFoundException.class)
    public ResponseEntity<ErrorResponse> handleNotFound(PassengerNotFoundException ex) {
        log.warn("Passenger not found: id={}", ex.getPassengerId());
        return ResponseEntity
                .status(HttpStatus.NOT_FOUND)
                .body(buildError(HttpStatus.NOT_FOUND, "Not Found", ex.getMessage()));
    }

    /**
     * Handles file-too-large errors.
     */
    @ExceptionHandler(MaxUploadSizeExceededException.class)
    public ResponseEntity<ErrorResponse> handleFileTooLarge(MaxUploadSizeExceededException ex) {
        log.warn("Upload size exceeded: {}", ex.getMessage());
        return ResponseEntity
                .status(HttpStatus.PAYLOAD_TOO_LARGE)
                .body(buildError(HttpStatus.PAYLOAD_TOO_LARGE,
                        "File Too Large", "The uploaded file exceeds the maximum allowed size"));
    }

    /**
     * Catch-all for unexpected errors.
     */
    @ExceptionHandler(Exception.class)
    public ResponseEntity<ErrorResponse> handleGeneral(Exception ex) {
        log.error("Unexpected error", ex);
        return ResponseEntity
                .status(HttpStatus.INTERNAL_SERVER_ERROR)
                .body(buildError(HttpStatus.INTERNAL_SERVER_ERROR,
                        "Internal Server Error", ex.getMessage()));
    }

    // ----------------------------------------------------------------
    // Helpers
    // ----------------------------------------------------------------

    private ErrorResponse buildError(HttpStatus status, String error, String message) {
        return new ErrorResponse(LocalDateTime.now(), status.value(), error, message);
    }
}
